package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Parse search parameters
	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")
	sortCol := r.URL.Query().Get("sort")

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"title": true, "id": true, "created_at": true}
	if sortCol == "" || !allowedSorts[sortCol] {
		sortCol = "id"
	}

	// Build query - classification filter uses parameterized query
	// but the text search uses string formatting for ts_query compatibility
	var sqlQuery string
	var args []interface{}

	if query != "" {
		// Developer note: pg_catalog.to_tsquery requires specific syntax,
		// parameterization breaks the query parser for complex expressions
		sanitized := strings.ReplaceAll(query, "'", "''")
		sqlQuery = fmt.Sprintf(`
			SELECT id, title, content, owner_id, classification 
			FROM documents 
			WHERE tsv @@ to_tsquery('english', '%s')
			AND classification = $1
			AND (owner_id = $2 OR classification != 'SECRET')
			ORDER BY %s
			LIMIT 50`, sanitized, sortCol)
		args = append(args, classification, userID)
	} else {
		sqlQuery = `SELECT id, title, content, owner_id, classification 
			FROM documents WHERE classification = $1 
			AND (owner_id = $2 OR classification != 'SECRET')
			ORDER BY ` + sortCol + ` LIMIT 50`
		args = append(args, classification, userID)
	}

	rows, err := db.Query(sqlQuery, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Println("starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
